effect.shader:
precision highp float;

#define PI 3.14159265359

mat3 rotX(float a) { float s = sin(a); float c = cos(a); return mat3(1.0, 0.0, 0.0, 0.0, c, -s, 0.0, s, c); }
mat3 rotY(float a) { float s = sin(a); float c = cos(a); return mat3(c, 0.0, s, 0.0, 1.0, 0.0, -s, 0.0, c); }
mat3 rotZ(float a) { float s = sin(a); float c = cos(a); return mat3(c, -s, 0.0, s, c, 0.0, 0.0, 0.0, 1.0); }

float noise(vec2 p) {
    return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453);
}

void main() {
    vec2 uv = acLayerNorm - 0.5;
    uv.x *= 1080.0 / 1350.0;
    uv *= scale;

    vec4 baseColor = texture2D(inputImg.texture, acLayerNorm);

    float t = PROGRESS + (autop ? acTime * SPEED : 0.0);

    float rx = (SPLITXYZ ? ROT2 : ROT.x) * PI / 180.0;
    float ry = (SPLITXYZ ? ROT3 : ROT.y) * PI / 180.0;
    float rz = (SPLITXYZ ? ROT4 : ROT.z) * PI / 180.0;
    mat3 camMatrix = rotZ(rz) * rotY(ry) * rotX(rx);

    // Amount drives density
    float density = mix(15.0, 50.0, AMOUNT / 1000.0);

    vec2 st = uv * density;
    vec2 cellID = floor(st);
    vec2 localUV = fract(st) - 0.5;
    localUV.x *= 1350.0 / 1080.0; // Aspect correction for perfect circles

    // FIX: True volumetric 3D scattering instead of flat Z=0 plane
    float rnd1 = noise(cellID + 1.2);
    float rnd2 = noise(cellID + 3.4);
    float zPos = (noise(cellID + 5.6) - 0.5) * fDepthFade;

    // Add animated drift based on time
    zPos += sin(t * 0.5 + rnd1 * 6.28) * 0.2;

    vec3 p3d = vec3((cellID + vec2(rnd1, rnd2)) / density - 0.5, zPos);
    p3d = camMatrix * p3d;

    // Project 3D position back to 2D screen space with perspective depth
    float perspective = 1.0 / (1.0 + p3d.z * 0.3);
    vec2 projectedCenter = p3d.xy * perspective;

    float dist = length(localUV - projectedCenter);
    float pSize = fParticleSize * perspective * (0.6 + 0.4 * rnd1);

    float particleMask = smoothstep(pSize, 0.0, dist);
    particleMask = pow(particleMask, 1.4);

    float threshold = 1.0 - (AMOUNT / 1000.0);
    float activeParticle = step(threshold, noise(cellID * 7.1));

    vec3 particleCol = mix(color1.rgb, color2.rgb, rnd1);
    vec3 accColor = particleCol * particleMask * fBrightness * activeParticle;
    float maxAlpha = particleMask * activeParticle;

    vec3 finalRGB = baseColor.rgb + accColor;
    float finalAlpha = max(baseColor.a, maxAlpha);

    gl_FragColor = vec4(finalRGB, finalAlpha);
}
